INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N067-01','CN0245','S067-01','共享站与催化剂边界','§6.2.2 p159-160；表4.14-1','一期环评共享站设计1200t/d，年237504.467m³、日719.711m³；蒸发浓缩脱氨及锰车间控制。实际是否建成、1000t/a新增项目边界待核。截图p160核年日量。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N067-02','CN0320','S067-05','产品边界','产品用途','钛酸正丁酯可作催化剂等多种用途，实际催化剂销售份额未知。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-03','CN0320','S067-03','项目投资及残余物','批复项目概况、固废治理','总投资58382.31万元、环保投资3600万元，均非污水单项。12000t/a焚烧炉是危废能力而非污水量。三效废盐和氯化铵按鉴定结论处置，鉴定前按危废管理。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N067-04','CN0320','S067-06','旧厂环保部及成本边界','1-1-130至132','设环保部负责污染治理和监测；历史环保支出含三效废水蒸发等设备，但混合集团费用不可作单厂污水成本；键兴子公司独立站不并入。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-05','CN0321','S067-09','市场及生产状态','问询回复钛酸正丁酯','2026年3月底有效订单155.20吨，非已交货产量；产品具体催化剂用途份额未知。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-06','CN0119','S067-10','历史危废处置及环保费用','1-1-102至103，危废表截图核对','2023H1、2022、2021、2020危废处置量20.03、1.49、0.58、1.05t，费用7.37、0.92、0.37、0.51万元，表列单价0.37、0.62、0.63、0.48万元/t。包含废反渗透膜、废液及其他危废，不拆为废水或膜浓液单价。日常环保费用71.82、169.15、136.25、49.40万元；环保设施60、24.11、803.81、909万元；披露明确未单独统计废气废水排放量，无法算吨水成本。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-07','CN0317','S067-10','正式批复','问询回复石嘴山项目','2023-07-17石经开环函〔2023〕10号，属于正式批复编号的公司披露，原批文未取得。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-08','CN0021','S067-12','公开部门','联系我们','供销部、技术开发部明确存在；个人关联号码及邮箱不采集；在线留言可作普通业务转接。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-09','CN0057','S067-14','业务渠道边界','联系页','厂址临淄区天辰路9号；官网有销售入口及环境社会风险投诉机制。投诉机制仅供原用途，不计营销渠道。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-10','CN0041','S067-16','办公与厂址边界','联系页','武汉办公地址光谷大道303号文馨楼1-301，非生产厂区；厂址及实际水处理需独立查。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-11','CN0110','S067-17','分期建设线索','官网检索摘要','综合2万t/a已有记录；2008、2012、2016分期建设线索需原文复核。官网复开502，不新增未完整复核的电话。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-12','CN0145','S067-18','经营身份和资金','公告被担保人及财务表','统一信用代码91370281595285227X，三维化学持股60%，2025收入1.546亿元、2026H1收入0.745亿元；新增授信担保额度3000万元不是环保预算。住所胶州经济技术开发区联东U谷21#102，不证明生产厂址。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N067-13','CN0242','S067-20','厂区范围','2024政府名单','孵化基地C区C11#位置线索；2026土壤地下水报告不能替代废水排口监测，独立厂址待核。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N067-14','CN0092','S067-21','主体及回收需求','企业基本情况及实际需求段','信用代码914206007068912209，襄城余家湖工业园天舜大道20号；自述硫酸催化剂制造及废催化剂回收需求，具体项目和水处理招采尚未明确；忽略页面油脂加工示例模板。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N067-15','CN0065','S067-22','生产设施','官网公司简介','2条生产线、厂房3000平方米；官网年产1000吨与旧记录一致不重复。环保类催化剂用于工业水、空气净化等；自身生产废水未获。','WEB_COMPANY','WEB_TEXT','2026-11-28');
